<?php
namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use App\Models\Qualification; use App\Models\DelaiTraitement;
class DelaiController extends Controller {public function index(){abort_unless(auth()->user()->isRole('ADMIN','RQ'),403);$delais=DelaiTraitement::with('qualification')->orderBy('module')->orderBy('qualification_id')->get();$qualifications=Qualification::where('actif',1)->orderBy('module')->orderBy('libelle')->get();return view('admin.delais',compact('delais','qualifications'));}public function store(Request $r){abort_unless(auth()->user()->isRole('ADMIN','RQ'),403);$d=$r->validate(['module'=>'required|in:reclamation,assistance','qualification_id'=>'nullable|exists:qualifications,id','libelle'=>'required|string|max:180','duree'=>'required|integer|min:1|max:8760','unite'=>'required|in:heures,jours','calendrier'=>'required|in:calendaire,ouvre','point_depart'=>'required|in:reception,affectation','alerte_avant'=>'required|integer|min:0|max:365','unite_alerte'=>'required|in:heures,jours','frequence_relance'=>'nullable|integer|min:1|max:365','unite_frequence_relance'=>'required|in:heures,jours','escalade_apres'=>'nullable|integer|min:1|max:365','date_debut'=>'required|date','date_fin'=>'nullable|date|after_or_equal:date_debut','actif'=>'nullable|boolean']);$d['cree_par']=auth()->id();$d['actif']=$r->boolean('actif');$q=DelaiTraitement::where('module',$d['module'])->where('qualification_id',$d['qualification_id']??null)->whereDate('date_debut',$d['date_debut'])->first();if($q)$q->update($d);else DelaiTraitement::create($d);return back()->with('success','Règle de délai enregistrée. Les dossiers affectés ultérieurement utiliseront la règle applicable.');}}
